import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.D1iekJsc.js";const u=JSON.parse('{"title":"Ollama LAN-Zugriff","description":"OLLAMA_HOST=0.0.0.0 und Firewall — Handy MiniTavern erreicht Ollama auf dem PC.","frontmatter":{"title":"Ollama LAN-Zugriff","description":"OLLAMA_HOST=0.0.0.0 und Firewall — Handy MiniTavern erreicht Ollama auf dem PC.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"Ollama LAN-Zugriff · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OLLAMA_HOST=0.0.0.0 und Firewall — Handy MiniTavern erreicht Ollama auf dem PC."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/ollama/lan"}]]},"headers":[],"relativePath":"de/ollama/lan.md","filePath":"de/ollama/lan.md","lastUpdated":1787224147000}'),l={name:"de/ollama/lan.md"};function s(r,e,o,d,h,p){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="lan-zugriff-ollama" tabindex="-1">LAN-Zugriff (Ollama) <a class="header-anchor" href="#lan-zugriff-ollama" aria-label="Permalink to &quot;LAN-Zugriff (Ollama)&quot;">​</a></h1><p>Standardmäßig oft nur Localhost. Handy → PC: Dienst auf <strong>allen Interfaces</strong> (<code>0.0.0.0</code>) und Firewall-Port.</p><h2 id="ollama-host-setzen" tabindex="-1"><code>OLLAMA_HOST</code> setzen <a class="header-anchor" href="#ollama-host-setzen" aria-label="Permalink to &quot;`OLLAMA_HOST` setzen&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>Start → «Umgebungsvariablen» → «Systemumgebungsvariablen bearbeiten» → «Umgebungsvariablen».</li><li>Unter Benutzer- oder Systemvariablen neu:</li></ol><table tabindex="0"><thead><tr><th>Name</th><th>Wert</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>Speichern, Ollama <strong>vollständig beenden und neu starten</strong> (Tray).</li></ol><p>PowerShell (nur aktuelle Session):</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dann Ollama-App oder Dienst neu starten</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Temporär (aktuelle Session):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>Dann Ollama beenden und neu öffnen. Nach Reboot ggf. Shell-Config oder LaunchAgent; alternativ:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>und Dienst in dieser Umgebung starten. Am sichersten: <strong>Variable setzen, Ollama neu starten</strong>.</p><h2 id="firewall-port-11434" tabindex="-1">Firewall Port 11434 <a class="header-anchor" href="#firewall-port-11434" aria-label="Permalink to &quot;Firewall Port 11434&quot;">​</a></h2><ul><li><strong>Windows</strong>: Einstellungen → Datenschutz &amp; Sicherheit → Windows-Sicherheit → Firewall → App erlauben; oder eingehende Regel TCP <code>11434</code>.</li><li><strong>macOS</strong>: Systemeinstellungen → Netzwerk → Firewall; Ollama erlauben oder Port freigeben.</li></ul><h2 id="lan-prufen" tabindex="-1">LAN prüfen <a class="header-anchor" href="#lan-prufen" aria-label="Permalink to &quot;LAN prüfen&quot;">​</a></h2><ol><li>PC-IP (siehe <a href="/ultra_guides/de/quickstart#step-4-lan-ip-des-pcs">Quickstart Step 4</a>).</li><li>Anderes Gerät im <strong>selben Wi‑Fi</strong>:</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>Ollama-Antwort = LAN ok.</p><h2 id="adresse-fur-minitavern" tabindex="-1">Adresse für MiniTavern <a class="header-anchor" href="#adresse-fur-minitavern" aria-label="Permalink to &quot;Adresse für MiniTavern&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>Hinweise:</p><ul><li>LAN-IP, <strong>kein</strong> <code>localhost</code></li><li>Suffix <code>/v1</code> (OpenAI-kompatibler Pfad)</li></ul><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><p><a href="/ultra_guides/de/connect-app/minitavern">In MiniTavern konfigurieren</a></p>',27)])])}const g=a(l,[["render",s]]);export{u as __pageData,g as default};
